children.text:
Total Amount: ₹{{ 
  tblCheques.selectedRows.reduce((sum, row) => sum + Number(row.amount), 0).toLocaleString('en-IN') 
}}

children.onClick:
{{
  BulkClearCheques.run().then(() => {
    showAlert('All Cheques Cleared Successfully!', 'success');
    getCheques.run(); // Refreshes the main table
    getUnconsumedCredits.run();
 getUnconsumedDebits.run();// Refreshes statement balances
    closeModal('ModalClearCheques');
  }).catch(e => {
    showAlert('Error: ' + (BulkClearCheques.data.error || e.message), 'error');
  });
}}

{{
  BounceCheque.run().then(() => {
    showAlert('Cheque bounced and reversals posted!', 'warning');
    getCheques.run(); // Refresh the list
    closeModal('ModalBounceCheque'); // Close the modal
    resetWidget('ModalBounceCheque'); // Reset the form fields
  }).catch(e => {
    showAlert('Error: ' + (BounceCheque.data.error || e.message), 'error');
  });
}}

{{
  apiUnclearCheque.run()
    .then(() => {
      showAlert('Cheque clearance reversed successfully!', 'success');

      // 1. Close the modal
      closeModal('mdlChequeRev');

      // 2. Refresh your main table (replace tblCheques with your actual table name)
      getCheques.run(); 

      // 3. Optional: Refresh bank balances if you have a widget for that
 getUnconsumedDebits.run();      getUnconsumedCredits.run();
    })
    .catch((err) => {
      showAlert('Failed to reverse: ' + err.message, 'error');
    })
}}

